update public.knowledge_base k
   set sources = s.urls, updated_at = now()
  from src s
 where k.category = s.category and k.title = s.title;

-- E-numre: Wikipedia og EFSAs forside erstattes af tre officielle sider (Fødevarestyrelsen, EFSA, EU-Kommissionen).
update public.knowledge_base
   set sources = array[$q$https://foedevarestyrelsen.dk/kost-og-foedevarer/foedevaresikkerhed/tilsaetninger/tilsaetningsstoffer$q$,$q$https://www.efsa.europa.eu/en/glossary/e-number$q$,$q$https://food.ec.europa.eu/safety/food-improvement-agents/additives_en$q$], updated_at = now()
 where category = 'e_number'
   and sources && array['https://en.wikipedia.org/wiki/E_number','https://www.efsa.europa.eu/en/topics/topic/food-additives'];

-- To do 0bf32b9d står åben: kilderne til ingredienser, retter og fun facts og den faglige gennemlæsning mangler.
insert into public.admin_todo_comments (todo_id, body)
select '0bf32b9d-62a2-4c07-afaa-f24c90bea64b',
       'Status 13. okt. 2026: 34 FAQ-spørgsmål, 8 kostformer og 247 E-numre peger nu på konkrete, officielle sider (Sundhed.dk, Astma-Allergi Danmark, Fødevarestyrelsen, Dansk Cøliaki Forening, EFSA, EU-Kommissionen, Lex) i stedet for forsider/Wikipedia. Adresserne svarer, og de er fundet via søgning på emnet. Jan har valgt at bruge tiden på videnskabeligt sikre kilder frem for at starte med en lægefaglig læser. Mangler: 342 ingredienser, 61 retter og 42 fun facts (ingen fælles artikel at pege på; forslag: vis ingen kilde frem for en forside), 4 FAQ uden god kilde (protein, palmeolie/palmekerneolie, solsikkeolie, økologisk), og omega-3 og jern støttes kun af brede sider, og den faglige gennemlæsning. Medicinsk rigtighed er stadig ikke vurderet.'
where exists (select 1 from public.admin_todos where id = '0bf32b9d-62a2-4c07-afaa-f24c90bea64b')
  and not exists (select 1 from public.admin_todo_comments where todo_id = '0bf32b9d-62a2-4c07-afaa-f24c90bea64b' and body like 'Status 13. okt. 2026: 34 FAQ%');
